<?php
namespace App\Http\Controllers;
use App\Models\{Project,Credential,ResourceUrl,Plan,VaultSetting}; use App\Services\{VaultCrypto,AuditService}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class BackupController extends Controller {
 public function index(){return view('backup.index');}
 public function export(VaultCrypto $c){$payload=json_encode(['format'=>'NEXOVAULT-BACKUP-2','created_at'=>now()->toIso8601String(),'projects'=>Project::all()->toArray(),'credentials'=>Credential::all()->toArray(),'urls'=>ResourceUrl::all()->toArray(),'plans'=>Plan::all()->toArray()],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$blob=$c->encrypt($payload,$c->sessionKey());AuditService::log('BACKUP_EXPORTED','Backup cifrado exportado.');return response("NEXOVAULT-BACKUP-2\n".$blob)->header('Content-Type','application/octet-stream')->header('Content-Disposition','attachment; filename="nexovault-backup-'.now()->format('Ymd-His').'.nvault"');}
 public function restore(Request $r,VaultCrypto $c){$r->validate(['backup'=>'required|file|max:51200','confirm'=>'required|in:RESTAURAR']);$raw=file_get_contents($r->file('backup')->getRealPath());[$header,$blob]=array_pad(preg_split('/\R/',$raw,2),2,null);if(!in_array(trim((string)$header),['NEXOVAULT-BACKUP-1','NEXOVAULT-BACKUP-2'],true)||!$blob)return back()->withErrors(['backup'=>'Archivo NexoVault no válido.']);try{$data=json_decode($c->decrypt(trim($blob),$c->sessionKey()),true,512,JSON_THROW_ON_ERROR);}catch(\Throwable){return back()->withErrors(['backup'=>'No se pudo descifrar o validar el backup con esta bóveda.']);}foreach(['projects','credentials','urls','plans'] as $k)if(!isset($data[$k])||!is_array($data[$k]))return back()->withErrors(['backup'=>'El backup está incompleto.']);DB::transaction(function()use($data){foreach($data['projects'] as $x){$id=$x['id']??null;if($id)Project::updateOrCreate(['id'=>$id],array_diff_key($x,['id'=>1,'created_at'=>1,'updated_at'=>1]));}foreach($data['credentials'] as $x){$id=$x['id']??null;if($id)Credential::updateOrCreate(['id'=>$id],array_diff_key($x,['id'=>1,'created_at'=>1,'updated_at'=>1]));}foreach($data['urls'] as $x){$id=$x['id']??null;if($id)ResourceUrl::updateOrCreate(['id'=>$id],array_diff_key($x,['id'=>1,'created_at'=>1,'updated_at'=>1]));}foreach($data['plans'] as $x){$id=$x['id']??null;if($id)Plan::updateOrCreate(['id'=>$id],array_diff_key($x,['id'=>1,'created_at'=>1,'updated_at'=>1]));}});AuditService::log('BACKUP_RESTORED','Backup cifrado restaurado.');return redirect()->route('dashboard')->with('ok','Backup restaurado correctamente.');}
}
